import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 14
    records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))

    if not records:
        return {"columns": [], "rows": []}

    number_pattern = re.compile(
        r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?"
    )

    def text_ratio(record):
        values = [value.strip() for value in record if value.strip()]
        if not values:
            return 0.0
        return sum(
            1 for value in values if not number_pattern.fullmatch(value)
        ) / len(values)

    candidates = [
        (index, record)
        for index, record in enumerate(records)
        if len(record) == expected_width
    ]

    if candidates:
        header_index, header = max(
            candidates,
            key=lambda item: (text_ratio(item[1]), -item[0]),
        )
    else:
        nonempty = [
            (index, record)
            for index, record in enumerate(records)
            if record and any(value.strip() for value in record)
        ]
        if not nonempty:
            return {"columns": [], "rows": []}
        header_index, header = max(
            nonempty,
            key=lambda item: (
                -abs(len(item[1]) - expected_width),
                text_ratio(item[1]),
                -item[0],
            ),
        )

    data_rows = records[header_index + 1 :]
    width = max([len(header)] + [len(row) for row in data_rows])

    columns = list(header)
    while len(columns) < width:
        columns.append(f"Extra {len(columns) - len(header) + 1}")

    rows = [list(row) + [""] * (width - len(row)) for row in data_rows]
    return {"columns": columns, "rows": rows}
